-- TOP4HoneyChains database schema after db/migrations up to 036_d98_seal_emptying.sql, for a new, empty database (D-98, db/install).
-- Generated by tools/DemoSchema (install mode) from the database TOP4HoneyChainsDb_install; schema only, no rows. Do not edit by hand.
-- Every object is created only when it does not exist, so the script can run again. SQL Server 2019, compatibility level 140 or 150.
-- Run: sqlcmd -S <server> -d <new database> -E -I -f 65001 -b -i db\install\01_schema.sql   (docs/KURULUM-TR.md, part B)

SET NOCOUNT ON;
DECLARE @users int = 0;
IF OBJECT_ID(N'dbo.AspNetUsers', N'U') IS NOT NULL
    EXEC sys.sp_executesql N'SELECT @n = COUNT(*) FROM dbo.AspNetUsers', N'@n int OUTPUT', @n = @users OUTPUT;
IF DB_NAME() IN (N'master', N'model', N'msdb', N'tempdb')
BEGIN
    RAISERROR(N'db/install: run this script in the new, empty TOP4HoneyChains database (sqlcmd -d <database>), not in %s.', 16, 1, N'a system database');
    SET NOEXEC ON;
END;
ELSE IF @users > 0
BEGIN
    RAISERROR(N'db/install: this database already has user accounts. db/install is only for a new, empty database; an existing database is updated with db/migrations.', 16, 1);
    SET NOEXEC ON;
END;
GO
